import pathlib,json,hashlib,datetime
D=pathlib.Path(__file__).resolve().parents[1];intake=json.loads((D/'outputs/intake.json').read_text());versions=json.loads((D/'outputs/versions.json').read_text())
# outcome, source labels, analysis, exact remaining task, numerical artifacts
notes={
334235:('parked_symbolic_reduction_gap','v1 Conjecture 25; published Conjecture 20 and Proposition 21','Source conjectures semilinear reducibility of completed zigzags and c2=-h(h+2) modulo every prime power, without bad primes. The source verifies h=3..8. Published PDF retains the conjecture. A finite point count does not establish semilinear reducibility. No source-formula evaluation is offered as discovery.','Produce uniform Dodgson-polynomial reduction beyond h=8, with literal reduction semantics; no such recurrence proved.',[]),
334318:('parked_deep_structural','v1 introduction JLPT conjecture','5-edge-connected loopless multigraphs must realize every zero-sum Z3 boundary by an orientation; 6-edge-connected case is already known. Small-order simple graph diagnostics do not cover multigraphs or prove the conjecture.','Need new full-scope 5-edge-connectivity argument or a certified missing boundary on a 5-edge-connected graph.',['outputs/orientations.json']),
334453:('parked_infinite_attainment_gap','v2 Conjecture 9.6; author-hosted published Monthly pages','For every fixed degree and finite forbidden-induced-subgraph list, finite extrema are conjectured. Choosing forbidden lists with empty admissible class would only give an excluded formulation correction. A finite sweep cannot disprove attainment over an unbounded class. No infinite strict-improvement family proved.','Exhibit a nonempty hereditary regular class and prove its extremal independent-set rate is not attained, or prove finite attainment. No finite experiment claimed.',[]),
334519:('excluded_published_refutation','v1/v2 Conjecture 4; Cambie-Jooken 2311.05542 Theorem 3.2','Later primary theorem explicitly gives a 4-regular graph G32 of girth at least 5 with occupancy fraction larger than that of H4,6 for every fugacity greater than 37. This exactly refutes the target. The later paper proof compares the two independence polynomials; no new search justified. Published Math. Comp. 95 (2026), 2091-2102, DOI 10.1090/mcom/4121.','No discovery work: already refuted. No claim of independently Lean-certifying the published G32.',[]),
334564:('parked_uniform_rounding_gap','v1 Conjecture 1.15','c(m) is existential and depends only on m. All 262144 ordered pairs of arbitrary edge sets of K3,3 admit a full perfect matching meeting both ceil(|Ei|/3) upper quotas. Thus this bounded case has deficit zero. This cannot refute or prove existence of a uniform c(m). The source conjectures even c(m)=m/2 might suffice.','Need rounding of the uniform fractional matching with bounded additive loss depending only on m, independent of order and maximum degree. A fixed-instance positive deficit is insufficient.',['outputs/quota.json']),
334569:('excluded_published_proof','v1 Conjecture 9; Admasu-Sehgal 1806.03774 Theorem 3.3 and Remarks 2-3','Later paper explicitly confirms Conjecture 9: positive terms give leading term (d-c+1)(b-a+1)p^(2a+b+c). Remark 3 says both Toth conjectures also follow from an earlier all-ranks degree/leading-coefficient result. No new elementary degree proof earns credit.','No new resolution; publisher version and underlying older all-ranks result not independently audited.',[]),
334829:('excluded_source_withdrawn','v1 Conjecture 2.10; v2 Conjecture 2.3; v3 replacement body','The nonexistence conjecture for balanced k-neighborly homology (2k-1)-spheres on 6k vertices occurs in v1/v2 and is absent from v3. The v3 paper reorganizes the lower-dimensional results, including a unique balanced 2-neighborly homology 4-sphere with 15 vertices and a non-spherical 5-manifold. No implication from that non-spherical example to a sphere is asserted. Brief treats a removed conjecture as withdrawn.','No attempt to claim a new refutation; version-of-record body not independently authenticated.',[]),
334889:('excluded_published_proof','v1 Conjecture 5.4; Alec Sun 1907.06623 Theorem 1.11','Sun determines the exact threshold N(r,s,k), explicitly resolving the source conjecture. The theorem handles coprime r<s; division by gcd and swapping/negating covers the remaining unequal cases, while the equal case is the original +/-1 result. JCTA 179 (2021), 105385. No new threshold proof attempted.','No discovery; ScienceDirect body not retrieved under inherited denial.',[]),
334926:('excluded_published_proof','v1-v3 Conjecture 2.4; Alishahi-Meunier 1704.02921 Theorem 1','The later theorem gives two disjoint independent sets covering all but one vertex in each color class, each satisfying |Si intersect Vj| >= |Vj|/2-1. Their total intersection size |Vj|-1 implies one of the two is strict on at least half of the classes. This is exactly the conjecture, including odd m by integrality. Later published EJC 24(3) P3.41, DOI 10.37236/7079, PDF retrieved.','No new result; prior proof body uses octahedral Tucker labeling.',[]),
373247:('parked_bounded_positive_diagnostics','2602.18244v1 Definition 2 and Conjecture 3.12','Use the source incidence-color convention: gamma(v,e)=-sigma(e)gamma(w,e), distinct colors at each vertex, palette 0,+/-1,...,+/-(n-2)/2. Normalize a star by switching. A perfect matching receives zero; positive-sign-product cycles in remaining spanning 2-factors receive +/- color pairs. Exhaustive K8 normalized signatures all pass a round-robin-pair template; 700 sampled signatures each at n=10,12,14,16 also pass. This is finite evidence only. The MathDB additional reference 1610.01676 actually retrieves Coloring Decompositions of Complete Geometric Graphs, not this signed-graph claim; not used as support.','Need balanced 2-factorization after deleting an appropriate perfect matching for every signature and every even order, or a literal non-colorability certificate. No universal theorem proved.',['outputs/signed-masks-8.json','outputs/signed-masks-10.json','outputs/signed-masks-12.json','outputs/signed-masks-14.json','outputs/signed-masks-16.json']),
329603:('parked_generic_stress_gap','v1/v2 Conjecture 1; paragraph after Theorem 4.8','The intended setting is generic uniformly expanding spherical frameworks. Dimensions at most 2 follow from the source theorems. The source isolates the higher-dimensional gap: a nonzero stress on a generic rigid spherical circuit must have nonzero sum of vertex stresses. Degenerate realizations and already-solved low dimensions cannot qualify. No generic symbolic rank calculation completed.','Prove the nonzero stress-sum lemma in d>=3 or exhibit a generic circuit where it vanishes identically; rational specializations alone do not prove generic failure.',[]),
329855:('parked_design_and_source_gap','v1 P1/P2 and Conjecture 3.29; Theorem 3.28','The source constructs many DCA families and obtains 3-MNOLS for every even order except possibly 146. It does not equate all MNOLS constructions with DCA satisfying P1/P2, so the spectrum theorem does not solve Conjecture 3.29. Re-enumerating tiny orders already printed would be uncredited. Institutional PDF retrieved is the v1 manuscript, not authenticated publisher typesetting.','Need a full-scope DCA construction with both P1 and P2, or a substantive nonexistence parameter. No exhaustive DCA search completed.',[]),
329942:('parked_intended_nonpower_search','v1 Definitions 6.2-6.3, Example 6.6, Conjecture 7.3','Source literal quantifier for every n exists A with |A| != (p-1)^n is weaker than its discussion of one cardinality outside all powers; trivial varying witnesses would be zero-credit wording work. Search targets the substantive discussion, using distinct-residue modular p-AP freeness and strictly increasing first p-1 residues for coverage. Source example S5(0,3) modulo 25 passes an independent convention sanity check. Completed p=5 searches N=11,17,23,25,49 and p=7,N=49 find no nonpower set. N=75,p=5 was killed at wall limit, no completion or coverage claim.','Need a uniform construction over odd primes of modular sets outside all powers. A fixed-prime example alone would not resolve all-prime scope; composite-modulus repeated-residue conventions require fidelity review.',['outputs/modular-5-11.json','outputs/modular-5-17.json','outputs/modular-5-23.json','outputs/modular-5-25.json','outputs/modular-5-49.json','outputs/modular-7-49.json','outputs/modular-sanity.json','logs/modular5-75.json']),
329971:('parked_infinite_probability','v1 Conjecture 5.1 and surrounding universal-cover discussion','Source conjectures nontrivial Bernoulli cumulative-merging percolation on bounded-degree infinite connected graphs. It identifies regular trees as a first step and explains why a universal-cover comparison is not available. A finite simulation cannot decide positive critical probability; disconnected/finite graph paraphrase defects would be excluded corrections.','Need uniform subcritical estimates on arbitrary bounded-degree graphs or an infinite connected bounded-degree construction with a rigorous endpoint critical parameter.',[]),
330095:('excluded_source_proved','v1 Lemma 3 and Theorem 4','The same one-page source explicitly proves Conjecture 2. Average permutation matrices depend only on orbit partitions; H and its orbit-partition stabilizer yield faces with a common relative interior point, hence equal faces and equal vertex groups. No discovery credit for formalizing that proof.','None for disposition.',[]),
330160:('excluded_published_proof','source difference-set conjecture; Ahmadi-Shafaeiabr 2108.10042 Theorem 1','Later primary theorem lists all eleven trinomials and proves their punctured value sets are Singer difference sets for every odd m>=5. Published FFA 90 (2023), 102195, DOI 10.1016/j.ffa.2023.102195. The correct ambient group order is 2^m-1; correcting the MathDB parameter typo is uncredited.','No new result; journal body not fetched under inherited ScienceDirect denial.',[]),
330175:('parked_geometric_partition','v1-v4 source Kano-Suzuki conjecture','Source establishes the hamburger theorem and partial colorful simplex partition regimes, retaining the larger-color-class conjecture. Disjointness means geometric simplices, not merely disjoint vertex blocks; ordinary equitable grouping is not a proof. No oriented-matroid or coordinate search completed.','Need noncrossing colorful simplex partition in all dimensions/colors, or an exact general-position configuration with a complete nonexistence certificate.',[]),
330178:('parked_bounded_positive_diagnostics','v1 Theorem 4.9 and Conjecture 4.10','Unsigned incident sums, not oriented conservation. Source proves the odd-regular cases other than degree 5. Backtracking labels 200 sampled 5-regular graphs (180 distinct labelled graphs) on even orders 6..24 using {-2,-1,1,2}; independent verification confirms every vertex sum zero, degree 5 and 2-edge-connectivity. No obstruction found.','Need uniform structural decomposition or a 2-edge-connected 5-regular graph with a certified unsatisfiable edge-labeling problem. Samples do not establish the conjecture.',['outputs/flows.json','outputs/flow-verification.json']),
330268:('excluded_source_refuted','v1-v5; v5 Theorem 3 and proof','The cited source itself disproves its Conjecture 3 for m>=4. A blue clique of order 2^m is a transversal; Hurwitz-Radon bounds red clique order by rho(2^m)<2^m, so no color-complementary transversal exists. Recreating that witness or its parameter instances earns zero.','None for disposition.',[]),
330331:('excluded_source_proved','v1-v3 Conjecture 1, Theorem 2 and proof','The source explicitly proves Shearer in a stronger form: n-vertex graphs with r cherries embed properly into locally n/(560 r^(3/4))-bounded colorings. For r<=sn and fixed k the permitted bound grows with n. This is the source resolution, not a new corollary for campaign credit.','None for disposition; journal body not independently fetched.',[])
}
results={}
for i,(outcome,labels,analysis,gap,artifacts) in notes.items():
 x=intake[str(i)];rec=x['record'];sources=[]
 for p in sorted((D/'sources').glob(str(i)+'-*receipt.json')):
  sr=json.loads(p.read_text());sources.append({'receipt':str(p.relative_to(D)),'url':sr.get('url'),'status':sr.get('status'),'sha256':sr.get('sha256')})
 results[str(i)]={'mathdb_id':i,'title':rec['title'],'statement':rec['statement'],'source_url':rec['source_url'],'provenance':{'chunk':x['chunk'],'line_1based':x['line'],'chunk_sha256':x['chunk_sha256'],'raw_sha256':x['raw_sha256'],'statement_utf8_sha256':hashlib.sha256(rec['statement'].encode()).hexdigest(),'raw_file':f'raw/{i}.jsonl'},'outcome':outcome,'accepted':False,'discovery_credit':0,'source_labels':labels,'analysis':analysis,'remaining_gap':gap,'review_depth':'Exact corpus record; all listed arXiv version PDFs acquired, selected primary statements and surrounding arguments reviewed. Later theorem/proof excerpts reviewed where cited. Not a full paper-by-paper or all-citing-work audit.','versions':versions[str(i)],'primary_receipts':sources,'history_check':'outputs/history-matches.txt (three numerical false positives, no target-specific historical disposition found by ID); title-alias history coverage incomplete','registry_screen':'outputs/registry-screen.json','literature_search_receipts':[str(p.relative_to(D)) for p in sorted((D/'outputs').glob('web-search-*.json'))],'numerical_artifacts':artifacts,'lean_endpoint':None,'lean_cost':'Finite refutations would be preferred. No general endpoint survives; no surrogate Lean theorem emitted.','novelty_cleared':False,'credit_risk':'Known/withdrawn gives zero credit.' if outcome.startswith('excluded') else 'Unresolved; bounded diagnostics give zero credit. Publisher and literature gaps remain.'}
assert len(results)==20 and set(map(int,results))==set(json.loads((D/'reservation.json').read_text())['ids'])
(D/'results.json').write_text(json.dumps(results,indent=2,ensure_ascii=False)+'\n')
print('entries',len(results),'excluded',sum(x['outcome'].startswith('excluded') for x in results.values()))
